export function PlayerPartnerHandlePlayFanfareOrBGM(): any {
  if (gBattleBufferA[gActiveBattler][3])
      {
          BattleStopLowHpSound();
          PlayBGM(gBattleBufferA[gActiveBattler][1] | (gBattleBufferA[gActiveBattler][2] << 8));
      }
      else
      {
          PlayFanfare(gBattleBufferA[gActiveBattler][1] | (gBattleBufferA[gActiveBattler][2] << 8));
      }

      PlayerPartnerBufferExecCompleted();
}

/** static void PlayerPartnerHandleFaintingCry(void) */
export function PlayerPartnerHandleFaintingCry(): any {
  let species: any = GetMonData(gPlayerParty[gBattlerPartyIndexes[gActiveBattler]], MON_DATA_SPECIES);

      PlayCry_ByMode(species, -25, CRY_MODE_FAINT);
      PlayerPartnerBufferExecCompleted();
}

/** static void PlayerPartnerHandleIntroSlide(void) */
export function PlayerPartnerHandleIntroSlide(): any {
  HandleIntroSlide(gBattleBufferA[gActiveBattler][1]);
      gIntroSlideFlags |= 1;
      PlayerPartnerBufferExecCompleted();
}

/** static void PlayerPartnerHandleIntroTrainerBallThrow(void) */
export function PlayerPartnerHandleIntroTrainerBallThrow(): any {
  let paletteNum: any = null;
      let taskId: any = null;

      SetSpritePrimaryCoordsFromSecondaryCoords(gSprites[gBattlerSpriteIds[gActiveBattler]]);

      gSprites[gBattlerSpriteIds[gActiveBattler]].data[0] = 50;
      gSprites[gBattlerSpriteIds[gActiveBattler]].data[2] = -40;
      gSprites[gBattlerSpriteIds[gActiveBattler]].data[4] = gSprites[gBattlerSpriteIds[gActiveBattler]].y;
      gSprites[gBattlerSpriteIds[gActiveBattler]].callback = StartAnimLinearTranslation;
      gSprites[gBattlerSpriteIds[gActiveBattler]].data[5] = gActiveBattler;

      StoreSpriteCallbackInData6(gSprites[gBattlerSpriteIds[gActiveBattler]], SpriteCB_FreePlayerSpriteLoadMonSprite);
      StartSpriteAnim(gSprites[gBattlerSpriteIds[gActiveBattler]], 1);

      paletteNum = AllocSpritePalette(0xD6F9);
      if (gPartnerTrainerId == TRAINER_STEVEN_PARTNER)
      {
          let spriteId: any = TRAINER_BACK_PIC_STEVEN;
          LoadCompressedPalette(gTrainerBackPicPaletteTable[spriteId].data, OBJ_PLTT_ID(paletteNum), PLTT_SIZE_4BPP);
      }
      else
      {
          let spriteId: any = GetFrontierTrainerFrontSpriteId(gPartnerTrainerId);
          LoadCompressedPalette(gTrainerFrontPicPaletteTable[spriteId].data, OBJ_PLTT_ID(paletteNum), PLTT_SIZE_4BPP);
      }


      gSprites[gBattlerSpriteIds[gActiveBattler]].oam.paletteNum = paletteNum;

      taskId = CreateTask(Task_StartSendOutAnim, 5);
      gTasks[taskId].data[0] = gActiveBattler;

      if (gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusSummaryShown)
          gTasks[gBattlerStatusSummaryTaskId[gActiveBattler]].func = Task_HidePartyStatusSummary;

      gBattleSpritesDataPtr.animationData.introAnimActive = TRUE;
      gBattlerControllerFuncs[gActiveBattler] = PlayerPartnerDummy;
}

/** static void Task_StartSendOutAnim(u8 taskId) */
export function Task_StartSendOutAnim(taskId: any): any {
  if (gTasks[taskId].data[1] < 24)
      {
          gTasks[taskId].data[1]++;
      }
      else
      {
          let savedActiveBank: any = gActiveBattler;

          gActiveBattler = gTasks[taskId].data[0];
          if (!IsDoubleBattle() || (gBattleTypeFlags & BATTLE_TYPE_MULTI))
          {
              gBattleBufferA[gActiveBattler][1] = gBattlerPartyIndexes[gActiveBattler];
              StartSendOutAnim(gActiveBattler, FALSE);
          }
          else
          {
              gBattleBufferA[gActiveBattler][1] = gBattlerPartyIndexes[gActiveBattler];
              StartSendOutAnim(gActiveBattler, FALSE);
              gActiveBattler ^= BIT_FLANK;
              gBattleBufferA[gActiveBattler][1] = gBattlerPartyIndexes[gActiveBattler];
              BattleLoadPlayerMonSpriteGfx(gPlayerParty[gBattlerPartyIndexes[gActiveBattler]], gActiveBattler);
              StartSendOutAnim(gActiveBattler, FALSE);
              gActiveBattler ^= BIT_FLANK;
          }
          gBattlerControllerFuncs[gActiveBattler] = Intro_ShowHealthbox;
          gActiveBattler = savedActiveBank;
          DestroyTask(taskId);
      }
}

/** static void PlayerPartnerHandleDrawPartyStatusSummary(void) */
export function PlayerPartnerHandleDrawPartyStatusSummary(): any {
  if (gBattleBufferA[gActiveBattler][1] != 0 && GetBattlerSide(gActiveBattler) == B_SIDE_PLAYER)
      {
          PlayerPartnerBufferExecCompleted();
      }
      else
      {
          gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusSummaryShown = 1;
          gBattlerStatusSummaryTaskId[gActiveBattler] = CreatePartyStatusSummarySprites(gActiveBattler,gBattleBufferA[gActiveBattler][4], gBattleBufferA[gActiveBattler][1], gBattleBufferA[gActiveBattler][2]);
          gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusDelayTimer = 0;

          if (gBattleBufferA[gActiveBattler][2] != 0)
              gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusDelayTimer = 93;

          gBattlerControllerFuncs[gActiveBattler] = EndDrawPartyStatusSummary;
      }
}

/** static void EndDrawPartyStatusSummary(void) */
export function EndDrawPartyStatusSummary(): any {
  if (gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusDelayTimer++ > 92)
      {
          gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusDelayTimer = 0;
          PlayerPartnerBufferExecCompleted();
      }
}

/** static void PlayerPartnerHandleHidePartyStatusSummary(void) */
export function PlayerPartnerHandleHidePartyStatusSummary(): any {
  if (gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusSummaryShown)
          gTasks[gBattlerStatusSummaryTaskId[gActiveBattler]].func = Task_HidePartyStatusSummary;
      PlayerPartnerBufferExecCompleted();
}

