export function PlayerPartnerHandleSpriteInvisibility(): any {
  if (IsBattlerSpritePresent(gActiveBattler))
      {
          gSprites[gBattlerSpriteIds[gActiveBattler]].invisible = gBattleBufferA[gActiveBattler][1];
          CopyBattleSpriteInvisibility(gActiveBattler);
      }
      PlayerPartnerBufferExecCompleted();
}

/** static void PlayerPartnerHandleBattleAnimation(void) */
export function PlayerPartnerHandleBattleAnimation(): any {
  if (!IsBattleSEPlaying(gActiveBattler))
      {
          let animationId: any = gBattleBufferA[gActiveBattler][1];
          let argument: any = gBattleBufferA[gActiveBattler][2] | (gBattleBufferA[gActiveBattler][3] << 8);

          if (TryHandleLaunchBattleTableAnimation(gActiveBattler, gActiveBattler, gActiveBattler, animationId, argument))
              PlayerPartnerBufferExecCompleted();
          else
              gBattlerControllerFuncs[gActiveBattler] = CompleteOnFinishedBattleAnimation;
      }
}

